      editable: $.Util.hasRoleFunc($.Dict.RoleFunc.AI_MACH_CONF.value),
      machLockerOptPermit: $.Util.hasRoleFunc($.Dict.RoleFunc.AI_MACH_LOCKER_OPT.value),
