                // '1200-1300' => {beginTime: '12:00', endTime: '13:00'}
                let list3 = t.split('-');
                let obj = { beginTime: list3[0], endTime: list3[1] };
                if (list3[0].length === 4) obj.beginTime = `${list3[0].substr(0, 2)}:${list3[0].substr(2)}`;
