            let obj2 = { weekDay };
            if ($.Util.isNotEmpty(weekDay) && weekDay === 7) {
              obj2.weekDay = 0;
            }
            if (openIds && openIds.length) obj2.openIds = openIds.join(',');
            if (closeIds && closeIds.length) obj2.closeIds = closeIds.join(',');
            if (times && times.length) obj2.times = times.map(j => `${j.beginTime.replace(/:/g, '')}-${j.endTime.replace(/:/g, '')}`).join(',');
