      couponFileds: ["memberPhoneNo", "code"],
      status: {
        1: "核销成功",
        2: "已撤销",
        3: "部分撤销"
      },
      isVerify: false,
      dyConsumeRole: $.Util.hasRoleFunc($.Dict.RoleFunc.POI_CONSUME.value),
      dyReverseConsumeRole: $.Util.hasRoleFunc($.Dict.RoleFunc.POI_REVERSE_CONSUME.value),
      buyCouponList: [],
