      const args = Object.assign({
        actionType: this.productId ? "U" : "I"
      }, { product: this.product });

      args.product.allowOtherType = this.isOnePlusN;

      for (let key in args.product) {
        if (args.product[key] === null || args.product[key] === undefined) {
          delete args.product[key];
        }
      }

