/* harmony default export */ __webpack_exports__["default"] = ({
  components: { Tinymce: __WEBPACK_IMPORTED_MODULE_0__components_tinymce___default.a },
  props: {},
  data() {
    return {
      inId: this.$route.params.inId,
      notice: {
        title: null,
        status: 99,
        content: null,
        pics: null,
        client: 0 // 0: 会员端、1：微官网、2：会员端、微官网
      },
      isPublish: false,
      picList: [],
      isShow: true
    };
  },
  computed: {},
  watch: {},
  created() {
    if (this.inId) {
      this.noticeQuery();
    }
  },
  mounted() {},
  methods: {
    noticeSave() {
      if (!this.notice.title) return $.Dlg.error("请输入公告标题");
      if (!this.notice.content) return $.Dlg.error("请输入公告正文内容");
      const args = {
        actionType: "I",
        notice: this.notice
      };
      if (this.inId) {
        args.actionType = "U";
        // 防止保存之后有撤销动作
        this.isShow = false;
        this.$nextTick(() => {
          this.isShow = true;
        });
      }
      args.notice.status = this.isPublish ? 0 : 99;
      this.handlerImg(args.notice.content);
      if (this.picList) {
        args.picList = this.picList;
      }
      $.Req.service($.SvName.INDEX_NOTICE_SAVE, args, ret => {
        $.Msg.success("操作成功！");
        if (args.actionType == "U") {
          this.noticeQuery();
        } else {
          this.$router.push("/notice");
        }
      }, true);
    },

    noticeQuery() {
      const args = {
        inId: this.inId
      };
      $.Req.service($.SvName.INDEX_NOTICE_QUERY, args, ret => {
        this.isPublish = ret.notice.status == 0 ? true : false;
        this.notice = ret.notice;
        let url = "{0}/{1}".format($.Conf.IMG_BASE_URL, encodeURIComponent($.data.tenant.encTid));
        const reg = /\/\/qdimg.oss-cn-shanghai.aliyuncs.com\/temp/g;
        this.notice.content = ret.notice.content.replace(eval(reg), url);
      }, true);
    },

    handlerImg(value) {
      // 使用dom
      const tempElement = document.createElement("div");
      tempElement.innerHTML = value;
      const imgElements = tempElement.getElementsByTagName("img");
      const srcValues = Array.from(imgElements).map(img => img.getAttribute("src"));
      // 输出所有src属性值
      this.picList = [];
      srcValues.forEach(item => {
        const arr = item.split($.Conf.IMG_BASE_URL);
        if (arr.length && arr[1]) {
          arr[1] = arr[1].replace("/temp/", "");
          arr[1] = arr[1].replace(`/${encodeURIComponent($.data.tenant.encTid)}/`, "");
          this.picList.push(arr[1]);
        }
      });
    }
  }
});

